{"command": "cd /tmp/t && cat > bw.py <<'EOF'
import subprocess, random

class BW:
    def __init__(self):
        self.bits=[]
    def put(self, val, n):
        for i in range(n):
            self.bits.append((val>>i)&1)
    def align(self):
        while len(self.bits)%8: self.bits.append(0)
    def bytes(self):
        out=bytearray()
        b=0; n=0
        for bit in self.bits:
            b |= bit<<n; n+=1
            if n==8: out.append(b); b=0; n=0
        if n: out.append(b)
        return bytes(out)
EOF
python3 - <<'EOF'
import subprocess, random, sys
sys.path.insert(0,'/tmp/t')
from bw import BW
random.seed(3)
def wbits_code(w, large=False):
    bw=BW()
    if large:
        bw.put(1,1); bw.put(0,3); bw.put(1,3); bw.put(w,5)
    elif w==16:
        bw.put(0,1)
    elif 17<=w<=24:
        bw.put(1,1); bw.put(w-17,3)
    else:
        bw.put(1,1); bw.put(0,3); bw.put(w-8,3)
    return bw
def craft(L, w=24, nfield=0, last=False):
    bw=wbits_code(w)
    bw.put(1 if last else 0, 1)   # ISLAST
    bw.put(nfield, 2)             # N
    mlen1 = L-1
    nb = 16 + 4*nfield
    bw.put(mlen1, nb)
    bw.put(1,1)                   # ISUNCOMPRESSED
    bw.align()
    data = bytes(random.getrandbits(8) for _ in range(L))
    out = bw.bytes() + data
    if not last:
        # trailing empty last metablock
        bw2=BW(); bw2.put(1,1); bw2.put(1,1)
        out += bw2.bytes()
    return out, data
# Test A: small L
for L in [1,5,100,65535]:
    s,d = craft(L)
    r=subprocess.run(['/workspace/executable','-f','-d','-o','/dev/stdout'],input=s,capture_output=True)
    print('L=%d n=0 ok=%s out==data:%s len=%d err=%s'%(L, r.returncode==0, r.stdout==d, len(r.stdout), r.stderr.decode().strip()[:50]))
# Test B: large L with N=1
for L in [65537, 200000, 524288]:
    s,d = craft(L, nfield=1)
    r=subprocess.run(['/workspace/executable','-f','-d','-o','/dev/stdout'],input=s,capture_output=True)
    print('L=%d n=1 ok=%s out==data:%s len=%d err=%s'%(L, r.returncode==0, r.stdout==d, len(r.stdout), r.stderr.decode().strip()[:50]))
EOF"}

