/* brotli-like command line tool (clean reimplementation from observed behaviour) */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <utime.h>
#include <getopt.h>
#include <grp.h>
#include <pwd.h>

#define PROGRAM_NAME "executable"
#define BROTLI_VERSION_STRING "brotli 1.2.0"

/* ------------------------------------------------------------------ */
/* usage / help                                                       */
/* ------------------------------------------------------------------ */
static const char *const kUsage[] = {
"Usage: " PROGRAM_NAME " [OPTION]... [FILE]...",
"Options:",
"  -#                          compression level (0-9)",
"  -c, --stdout                write on standard output",
"  -d, --decompress            decompress",
"  -f, --force                 force output file overwrite",
"  -h, --help                  display this help and exit",
"  -j, --rm                    remove source file(s)",
"  -s, --squash                remove destination file if larger than source",
"  -k, --keep                  keep source file(s) (default)",
"  -n, --no-copy-stat          do not copy source file(s) attributes",
"  -o FILE, --output=FILE      output file (only if 1 input file)",
"  -q NUM, --quality=NUM       compression level (0-11)",
"  -t, --test                  test compressed file integrity",
"  -v, --verbose               verbose mode",
"  -w NUM, --lgwin=NUM         set LZ77 window size (0, 10-24)",
"                              window size = 2**NUM - 16",
"                              0 lets compressor choose the optimal value",
"  --large_window=NUM          use incompatible large-window brotli",
"                              bitstream with window size (0, 10-30)",
"                              WARNING: this format is not compatible",
"                              with brotli RFC 7932 and may not be",
"                              decodable with regular brotli decoders",
"  -C B64, --comment=B64       set comment; argument is base64-decoded first;",
"                              (maximal decoded length: 80)",
"                              when decoding: check stream comment;",
"                              when encoding: embed comment (fingerprint)",
"  -D FILE, --dictionary=FILE  use FILE as raw (LZ77) dictionary",
"  -K, --concatenated          allows concatenated brotli streams as input",
"  -S SUF, --suffix=SUF        output file suffix (default:'.br')",
"  -V, --version               display version and exit",
"  -Z, --best                  use best compression level (11) (default)",
"Simple options could be coalesced, i.e. '-9kf' is equivalent to '-9 -k -f'.",
"With no FILE, or when FILE is -, read standard input.",
"All arguments after '--' are treated as files.",
NULL};

static void PrintUsage(FILE *out) {
  int i;
  for (i = 0; kUsage[i]; i++) fprintf(out, "%s\n", kUsage[i]);
}

static void Fatal(void) {
  PrintUsage(stdout);
  exit(1);
}

/* ------------------------------------------------------------------ */
/* options                                                            */
/* ------------------------------------------------------------------ */
typedef struct {
  int mode_decompress, mode_test, mode_verbose, mode_stdout, mode_rm;
  int mode_keep, mode_copy_stat, mode_force, mode_squash, mode_concat;
  int quality;
  int lgwin;            /* -1 = not set */
  int large_window;
  const char *suffix;
  const char *output;
  const char *dictionary;
  unsigned char comment[80];
  int comment_len;
  int have_comment;
  int dictionary_set;
  int have_quality, have_lgwin, have_output, have_suffix, have_dictionary;
  int have_comment_opt;
  int version;
  int help;
} Options;

static int ParseInt(const char *s, int *out) {
  char *end = NULL;
  long v;
  if (!s || !*s) return 0;
  v = strtol(s, &end, 10);
  if (end == s || *end) return 0;
  *out = (int)v;
  return 1;
}

static int Base64Decode(const char *in, unsigned char *out, int maxlen) {
  static const int tbl[256] = {0};
  static int init = 0;
  int i, acc = 0, bits = 0, len = 0;
  int T[256];
  if (!init) {
    const char *cs = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    for (i = 0; i < 256; i++) T[i] = -1;
    for (i = 0; i < 64; i++) T[(unsigned char)cs[i]] = i;
    init = 1;
    for (i = 0; i < 256; i++) ((int*)tbl)[i] = T[i];
  } else {
    for (i = 0; i < 256; i++) T[i] = ((const int*)tbl)[i];
  }
  {
    /* recompute each time (simple, avoids global state bugs) */
    const char *cs = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    int j;
    for (j = 0; j < 256; j++) T[j] = -1;
    for (j = 0; j < 64; j++) T[(unsigned char)cs[j]] = j;
  }
  for (i = 0; in[i]; i++) {
    int c = (unsigned char)in[i];
    int v;
    if (c == '=') {
      if (in[i+1]) return -1;
      break;
    }
    v = T[c];
    if (v < 0) return -1;
    acc = (acc << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      if (len >= maxlen) return -1;
      out[len++] = (unsigned char)(acc >> bits);
    }
  }
  if (bits >= 6) return -1;  /* dangling bits */
  return len;
}

/* ------------------------------------------------------------------ */
/* bit writer / reader                                                */
/* ------------------------------------------------------------------ */
typedef struct { unsigned char *buf; size_t cap, len; uint32_t acc; int nbits; } BitW;

static void bw_init(BitW *w) { w->buf = NULL; w->cap = 0; w->len = 0; w->acc = 0; w->nbits = 0; }
static void bw_free(BitW *w) { free(w->buf); w->buf = NULL; }
static void bw_put(BitW *w, uint32_t val, int n) {
  int i;
  for (i = 0; i < n; i++) {
    w->acc |= ((val >> i) & 1u) << w->nbits;
    w->nbits++;
    if (w->nbits == 8) {
      if (w->len == w->cap) { w->cap = w->cap ? w->cap * 2 : 4096; w->buf = realloc(w->buf, w->cap); }
      w->buf[w->len++] = (unsigned char)w->acc;
      w->acc = 0; w->nbits = 0;
    }
  }
}
static void bw_align(BitW *w) { while (w->nbits) bw_put(w, 0, 1); }
static unsigned char *bw_bytes(BitW *w, size_t *len) {
  bw_align(w);
  *len = w->len;
  return w->buf;
}

/* ------------------------------------------------------------------ */
/* stream construction: uncompressed meta-blocks                      */
/* ------------------------------------------------------------------ */
static void PutWindowBits(BitW *w, int lgwin, int large_window) {
  if (!large_window) {
    if (lgwin == 16) { bw_put(w, 0, 1); return; }
    if (lgwin >= 17 && lgwin <= 24) { bw_put(w, 1, 1); bw_put(w, (unsigned)(lgwin - 17), 3); return; }
    bw_put(w, 1, 1); bw_put(w, 0, 3); bw_put(w, (unsigned)(lgwin - 8), 3);
    return;
  }
  if (lgwin >= 10 && lgwin <= 24) { PutWindowBits(w, lgwin, 0); return; }
  if (lgwin >= 25 && lgwin <= 30) {
    bw_put(w, 1, 1); bw_put(w, 0, 3); bw_put(w, 1, 3); bw_put(w, (unsigned)lgwin, 5);
    return;
  }
  PutWindowBits(w, lgwin, 0);
}

/* number of bits needed */
static int NibblesForMlen(uint32_t mlen1) {
  int x = 0;
  while (x < 3 && mlen1 >= (1u << (12 + 4 * (x + 1)))) x++;
  if (mlen1 >= 65536u) {
    while (x < 2 && mlen1 >= (1u << (16 + 4 * (x + 1)))) x++;
  }
  return x;
}

static void PutMetablockHeader(BitW *w, int is_last, uint32_t mlen, int is_uncompressed) {
  int x;
  bw_put(w, is_last ? 1u : 0u, 1);
  if (is_last) bw_put(w, 0u, 1); /* is_last_empty = 0 */
  x = NibblesForMlen(mlen - 1);
  bw_put(w, (unsigned)x, 2);
  bw_put(w, mlen - 1, 16 + 4 * x);
  if (is_uncompressed) bw_put(w, 1u, 1);
  else bw_put(w, 0u, 1);
}

/* write whole stream as sequence of uncompressed meta blocks */
static int EncodeUncompressed(const unsigned char *data, size_t len, int lgwin,
                              int large_window, const unsigned char *comment, int clen,
                              unsigned char **outp, size_t *outlen) {
  BitW w;
  size_t pos = 0;
  size_t total_cap = len + 64;
  unsigned char *acc = NULL;
  size_t acc_len = 0, acc_cap = 0;
  bw_init(&w);
  PutWindowBits(&w, lgwin, large_window);
  if (len == 0) {
    bw_put(&w, 1, 1); /* is_last */
    bw_put(&w, 1, 1); /* is_last_empty */
  }
  while (pos < len) {
    size_t chunk = len - pos;
    if (chunk > 524288) chunk = 524288;
    PutMetablockHeader(&w, (pos + chunk == len) ? 1 : 0, (uint32_t)chunk, 1);
    bw_align(&w);
    { size_t l; unsigned char *b = bw_bytes(&w, &l);
      if (acc_len + l > acc_cap) { acc_cap = (acc_len + l + len + 64); acc = realloc(acc, acc_cap); }
      memcpy(acc + acc_len, b, l); acc_len += l; }
    free(w.buf); w.buf = NULL; w.cap = 0; w.len = 0; w.acc = 0; w.nbits = 0;
    { size_t i; for (i = 0; i < chunk; i++) {
        if (acc_len == acc_cap) { acc_cap *= 2; acc = realloc(acc, acc_cap); }
        acc[acc_len++] = data[pos + i];
      } }
    pos += chunk;
  }
  if (len == 0) { size_t l; unsigned char *b = bw_bytes(&w, &l);
    if (acc_len + l > acc_cap) { acc_cap = acc_len + l + 8; acc = realloc(acc, acc_cap); }
    memcpy(acc + acc_len, b, l); acc_len += l; free(w.buf); w.buf=NULL; }
  else { free(w.buf); }
  *outp = acc; *outlen = acc_len;
  return 0;
}

/* ------------------------------------------------------------------ */
/* decoding: minimal brotli decoder                                   */
/* ------------------------------------------------------------------ */
typedef struct {
  const unsigned char *buf;
  size_t len, pos;
  uint32_t acc;
  int nbits;
} BitR;

static int br_init(BitR *r, const unsigned char *b, size_t l) {
  r->buf = b; r->len = l; r->pos = 0; r->acc = 0; r->nbits = 0;
  return 1;
}
static int br_fill(BitR *r, int n) {
  while (r->nbits < n) {
    if (r->pos >= r->len) return 0;
    r->acc |= (uint32_t)r->buf[r->pos++] << r->nbits;
    r->nbits += 8;
  }
  return 1;
}
static int br_read(BitR *r, int n, uint32_t *out) {
  if (n == 0) { *out = 0; return 1; }
  if (!br_fill(r, n)) return 0;
  *out = r->acc & ((1u << n) - 1u);
  r->acc >>= n; r->nbits -= n;
  return 1;
}
static void br_align(BitR *r) { r->acc = 0; r->nbits = 0; }

static int ReadWindowBits(BitR *r, int *lgwin) {
  uint32_t b;
  if (!br_read(r, 1, &b)) return 0;
  if (!b) { *lgwin = 16; return 1; }
  if (!br_read(r, 3, &b)) return 0;
  if (b) { *lgwin = 17 + (int)b; return 1; }
  if (!br_read(r, 3, &b)) return 0;
  if (b == 1) { if (!br_read(r, 5, &b)) return 0; *lgwin = (int)b; return 1; }
  if (b == 0) { *lgwin = 17; return 1; }
  *lgwin = (int)b + 8;
  return 1;
}

/* decode a stream; returns 0 on success */
static int DecodeStream(const unsigned char *in, size_t inlen, size_t *consumed,
                        unsigned char **outp, size_t *outlen, int *had_error) {
  BitR r;
  uint32_t v;
  int lgwin, is_last, is_last_empty, x, is_uncomp;
  uint32_t mlen;
  if (!br_init(&r, in, inlen)) return 1;
  if (!ReadWindowBits(&r, &lgwin)) return 1;
  *outp = NULL; *outlen = 0; *had_error = 0;
  for (;;) {
    size_t op;
    unsigned char *nb;
    if (!br_read(&r, 1, &v)) return 1;
    is_last = (int)v;
    if (is_last) {
      if (!br_read(&r, 1, &v)) return 1;
      is_last_empty = (int)v;
      if (is_last_empty) { *consumed = r.pos - (size_t)(r.nbits / 8); break; }
    }
    if (!br_read(&r, 2, &v)) return 1;
    x = (int)v;
    if (x > 2) return 1;
    if (!br_read(&r, 16 + 4 * x, &v)) return 1;
    mlen = v + 1;
    if (mlen > (1u << 24)) return 1;
    if (x > 0) {
      if (mlen - 1 < (1u << (12 + 4 * x))) return 1;
    }
    if (!br_read(&r, 1, &v)) return 1;
    is_uncomp = (int)v;
    if (!is_uncomp) return 1;   /* compressed meta-blocks not supported */
    br_align(&r);
    nb = realloc(*outp, *outlen + mlen);
    if (!nb) return 1;
    *outp = nb;
    for (op = 0; op < mlen; op++) {
      if (!br_fill(&r, 8)) return 1;
      nb[*outlen + op] = (unsigned char)(r.acc & 0xffu);
      r.acc >>= 8; r.nbits -= 8;
    }
    *outlen += mlen;
    if (is_last) {
      *consumed = r.pos - (size_t)(r.nbits / 8);
      break;
    }
  }
  return 0;
}

/* ------------------------------------------------------------------ */
/* file helpers                                                       */
/* ------------------------------------------------------------------ */
static int CopyStat(const char *src, const char *dst) {
  struct stat st;
  if (stat(src, &st) != 0) return 0;
  {
    struct utimbuf tb;
    tb.actime = st.st_atime;
    tb.modtime = st.st_mtime;
    if (chmod(dst, st.st_mode & 07777) != 0)
      fprintf(stderr, "setting access bits failed for [%s]: %s\n", dst, strerror(errno));
    if (chown(dst, st.st_uid, (gid_t)-1) != 0 && (geteuid() != st.st_uid))
      fprintf(stderr, "setting user failed for [%s]: %s\n", dst, strerror(errno));
    if (chown(dst, (uid_t)-1, st.st_gid) != 0 && (getegid() != st.st_gid))
      fprintf(stderr, "setting group failed for [%s]: %s\n", dst, strerror(errno));
    utime(dst, &tb);
  }
  return 1;
}

static void PrintTiming(const char *kind, const char *name, size_t in, size_t out) {
  fprintf(stderr, "%s [%s]: %zu B -> %zu B in 0.00 sec\n", kind, name, in, out);
}

/* ------------------------------------------------------------------ */
int main(int argc, char **argv) {
  Options o;
  int i, argi, nfiles = 0;
  char **files;
  int args_end = 0;
  int rc = 0;

  memset(&o, 0, sizeof(o));
  o.quality = 11;
  o.lgwin = -1;
  o.large_window = -1;
  o.suffix = ".br";
  o.mode_keep = 1;
  o.mode_copy_stat = 1;

  files = (char **)malloc(sizeof(char *) * (argc + 2));
  if (!files) return 1;

  for (argi = 1; argi < argc; argi++) {
    char *a = argv[argi];
    if (!args_end && a[0] == '-' && a[1]) {
      if (a[1] == '-') {
        /* long option */
        char *name = a + 2, *eq = strchr(name, '=');
        size_t nl = eq ? (size_t)(eq - name) : strlen(name);
        char tmp[64];
        if (nl >= sizeof(tmp)) nl = sizeof(tmp) - 1;
        memcpy(tmp, name, nl); tmp[nl] = 0;
        if (!strcmp(tmp, "")) { args_end = 1; continue; }
        else if (!strcmp(tmp, "decompress")) o.mode_decompress = 1;
        else if (!strcmp(tmp, "stdout")) o.mode_stdout = 1;
        else if (!strcmp(tmp, "test")) o.mode_test = 1;
        else if (!strcmp(tmp, "force")) o.mode_force = 1;
        else if (!strcmp(tmp, "help")) { PrintUsage(stderr); exit(0); }
        else if (!strcmp(tmp, "version")) { puts(BROTLI_VERSION_STRING); exit(0); }
        else if (!strcmp(tmp, "rm")) o.mode_rm = 1;
        else if (!strcmp(tmp, "keep")) o.mode_keep = 1;
        else if (!strcmp(tmp, "squash")) o.mode_squash = 1;
        else if (!strcmp(tmp, "no-copy-stat")) o.mode_copy_stat = 0;
        else if (!strcmp(tmp, "concatenated")) o.mode_concat = 1;
        else if (!strcmp(tmp, "verbose")) {
          if (o.mode_verbose) { fprintf(stderr, "argument --verbose / -v already set\n"); Fatal(); }
          o.mode_verbose = 1;
        }
        else if (!strcmp(tmp, "quality") || !strcmp(tmp, "lgwin") ||
                 !strcmp(tmp, "large_window") || !strcmp(tmp, "output") ||
                 !strcmp(tmp, "suffix") || !strcmp(tmp, "comment") ||
                 !strcmp(tmp, "dictionary")) {
          const char *val;
          if (!eq) { fprintf(stderr, "must pass the parameter as --%s=value\n", tmp); Fatal(); }
          val = eq + 1;
          if (!strcmp(tmp, "quality")) {
            if (o.have_quality) { fprintf(stderr, "argument --quality / -q already set\n"); Fatal(); }
            if (!ParseInt(val, &o.quality) || o.quality < 0 || o.quality > 11) {
              fprintf(stderr, "error parsing quality value [%s]\n", val); Fatal();
            }
            o.have_quality = 1;
          } else if (!strcmp(tmp, "lgwin")) {
            if (o.have_lgwin) { fprintf(stderr, "argument --lgwin / -w already set\n"); Fatal(); }
            if (!ParseInt(val, &o.lgwin)) { fprintf(stderr, "error parsing lgwin value [%s]\n", val); Fatal(); }
            if (o.lgwin < 10) { fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (10)\n", o.lgwin); Fatal(); }
            if (!o.large_window && o.lgwin > 24) { fprintf(stderr, "error parsing lgwin value [%s]\n", val); Fatal(); }
            o.have_lgwin = 1;
          } else if (!strcmp(tmp, "large_window")) {
            if (o.have_lgwin) { fprintf(stderr, "argument --lgwin / -w already set\n"); Fatal(); }
            if (!ParseInt(val, &o.lgwin)) { fprintf(stderr, "error parsing lgwin value [%s]\n", val); Fatal(); }
            if (o.lgwin < 10) { fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (10)\n", o.lgwin); Fatal(); }
            if (o.lgwin > 30) { fprintf(stderr, "error parsing lgwin value [%s]\n", val); Fatal(); }
            o.large_window = 1; o.have_lgwin = 1;
          } else if (!strcmp(tmp, "output")) {
            if (o.have_output) { fprintf(stderr, "argument --output / -o already set\n"); Fatal(); }
            o.output = val; o.have_output = 1;
          } else if (!strcmp(tmp, "suffix")) {
            if (o.have_suffix) { fprintf(stderr, "argument --suffix / -S already set\n"); Fatal(); }
            o.suffix = val; o.have_suffix = 1;
          } else if (!strcmp(tmp, "comment")) {
            int n = Base64Decode(val, o.comment, 80);
            if (n < 0) { fprintf(stderr, "invalid base64-encoded comment\n"); Fatal(); }
            o.comment_len = n; o.have_comment = 1; o.have_comment_opt = 1;
          } else {
            if (o.have_dictionary) { fprintf(stderr, "argument --dictionary / -D already set\n"); Fatal(); }
            o.dictionary = val; o.have_dictionary = 1; o.dictionary_set = 1;
          }
        }
        else { fprintf(stderr, "must pass the parameter as --%s=value\n", tmp); Fatal(); }
        continue;
      }
      /* short options, possibly coalesced */
      {
        char *p = a + 1;
        while (*p) {
          char c = *p;
          switch (c) {
            case 'c': o.mode_stdout = 1; break;
            case 'd': o.mode_decompress = 1; break;
            case 'f': o.mode_force = 1; break;
            case 't': o.mode_test = 1; break;
            case 'j': o.mode_rm = 1; break;
            case 'k': o.mode_keep = 1; break;
            case 's': o.mode_squash = 1; break;
            case 'n': o.mode_copy_stat = 0; break;
            case 'K': o.mode_concat = 1; break;
            case 'Z': o.quality = 11; break;
            case 'v':
              if (o.mode_verbose) { fprintf(stderr, "argument --verbose / -v already set\n"); Fatal(); }
              o.mode_verbose = 1; break;
            case 'h': PrintUsage(stderr); exit(0);
            case 'V': puts(BROTLI_VERSION_STRING); exit(0);
            default: {
              int val_int;
              if (c >= '0' && c <= '9') {
                if (o.have_quality) { fprintf(stderr, "argument --quality / -q already set\n"); Fatal(); }
                o.quality = c - '0'; o.have_quality = 1; p++; continue;
              }
              if (c == 'q' || c == 'w' || c == 'o' || c == 'S' || c == 'C' || c == 'D') {
                const char *val;
                if (p[1]) { val = p + 1; p = ""; }
                else { if (argi + 1 >= argc) { fprintf(stderr, "expected parameter for argument -%c\n", c); Fatal(); }
                       val = argv[++argi]; }
                if (c == 'q') {
                  if (o.have_quality) { fprintf(stderr, "argument --quality / -q already set\n"); Fatal(); }
                  if (!ParseInt(val, &o.quality) || o.quality < 0 || o.quality > 11) {
                    fprintf(stderr, "error parsing quality value [%s]\n", val); Fatal(); }
                  o.have_quality = 1;
                } else if (c == 'w') {
                  if (o.have_lgwin) { fprintf(stderr, "argument --lgwin / -w already set\n"); Fatal(); }
                  if (!ParseInt(val, &o.lgwin)) { fprintf(stderr, "error parsing lgwin value [%s]\n", val); Fatal(); }
                  if (o.lgwin < 10) { fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (10)\n", o.lgwin); Fatal(); }
                  if (o.lgwin > 24) { fprintf(stderr, "error parsing lgwin value [%s]\n", val); Fatal(); }
                  o.have_lgwin = 1;
                } else if (c == 'o') {
                  if (o.have_output) { fprintf(stderr, "argument --output / -o already set\n"); Fatal(); }
                  o.output = val; o.have_output = 1;
                } else if (c == 'S') {
                  if (o.have_suffix) { fprintf(stderr, "argument --suffix / -S already set\n"); Fatal(); }
                  o.suffix = val; o.have_suffix = 1;
                } else if (c == 'C') {
                  int n = Base64Decode(val, o.comment, 80);
                  if (n < 0) { fprintf(stderr, "invalid base64-encoded comment\n"); Fatal(); }
                  o.comment_len = n; o.have_comment = 1; o.have_comment_opt = 1;
                } else {
                  if (o.have_dictionary) { fprintf(stderr, "argument --dictionary / -D already set\n"); Fatal(); }
                  o.dictionary = val; o.have_dictionary = 1; o.dictionary_set = 1;
                }
                break;
              }
              fprintf(stderr, "invalid argument -%c\n", c); Fatal();
            }
          }
          if (!*p) break;
          p++;
        }
      }
      continue;
    }
    if (!args_end && a[0] == '-' && !a[1]) { files[nfiles++] = a; continue; }
    files[nfiles++] = a;
  }

  if (nfiles == 0) { files[0] = (char *)"-"; nfiles = 1; }

  for (i = 0; i < nfiles; i++) {
    const char *inname = files[i];
    int use_stdin = (strcmp(inname, "-") == 0);
    char *outname = NULL;
    FILE *fin = stdin, *fout = NULL;
    unsigned char *inbuf = NULL, *outbuf = NULL;
    size_t inlen = 0, incap = 0, outlen = 0;
    int destroy_src = 0;

    if (!use_stdin) {
      struct stat st;
      if (stat(inname, &st) != 0) {
        fprintf(stderr, "failed to open input file [%s]: %s\n", inname, strerror(errno));
        rc = 1; goto cleanup;
      }
      if (!o.mode_decompress && !o.mode_test && o.lgwin < 0) {
        /* choose window from file size */
        uint64_t sz = (uint64_t)st.st_size;
        int w = 10;
        uint64_t need = sz + 16;
        while ((1ull << w) < need && w < 30) w++;
        if (w < 10) w = 10;
        if (o.quality <= 1) { if (w < 18) w = 18; }
        if (w > 24) w = 24;
        o.lgwin = w;
      }
      fin = fopen(inname, "rb");
      if (!fin) { fprintf(stderr, "failed to open input file [%s]: %s\n", inname, strerror(errno)); rc = 1; goto cleanup; }
    } else if (o.lgwin < 0) {
      o.lgwin = o.large_window ? 24 : (o.quality <= 1 ? 24 : 24);
    }

    if (!o.mode_decompress && !o.mode_test) {
      /* compression */
      while (1) {
        size_t got;
        if (inlen == incap) { incap = incap ? incap * 2 : 65536; inbuf = realloc(inbuf, incap); if (!inbuf) { rc = 1; goto cleanup; } }
        got = fread(inbuf + inlen, 1, incap - inlen, fin);
        if (got == 0) break;
        inlen += got;
      }
      if (ferror(fin)) { fprintf(stderr, "failed to read input [%s]: %s\n", inname, strerror(errno)); rc = 1; goto cleanup; }
      if (EncodeUncompressed(inbuf, inlen, o.lgwin, o.large_window > 0, o.comment, o.comment_len, &outbuf, &outlen) != 0) {
        fprintf(stderr, "compression failed\n"); rc = 1; goto cleanup;
      }
      if (o.mode_stdout) {
        fwrite(outbuf, 1, outlen, stdout);
      } else if (o.output) {
        outname = strdup(o.output);
      } else {
        size_t l = strlen(inname) + strlen(o.suffix) + 1;
        outname = malloc(l); snprintf(outname, l, "%s%s", inname, o.suffix);
      }
      if (!o.mode_stdout) {
        FILE *t;
        if (!o.mode_force && !use_stdin) {
          struct stat st2;
          if (stat(outname, &st2) == 0) {
            fprintf(stderr, "failed to open output file [%s]: File exists\n", outname);
            rc = 1; goto cleanup;
          }
        }
        t = fopen(outname, "wb");
        if (!t) { fprintf(stderr, "failed to open output file [%s]: %s\n", outname, strerror(errno)); rc = 1; goto cleanup; }
        fwrite(outbuf, 1, outlen, t);
        fclose(t);
        if (o.mode_copy_stat && !use_stdin) CopyStat(inname, outname);
        if (o.mode_verbose) PrintTiming("Compressed", inname, inlen, outlen);
        if (o.mode_rm && !use_stdin) destroy_src = 1;
      } else {
        if (o.mode_verbose) PrintTiming("Compressed", inname, inlen, outlen);
        if (o.mode_rm && !use_stdin) destroy_src = 1;
      }
    } else {
      /* decompression / test */
      while (1) {
        size_t got;
        if (inlen == incap) { incap = incap ? incap * 2 : 65536; inbuf = realloc(inbuf, incap); if (!inbuf) { rc = 1; goto cleanup; } }
        got = fread(inbuf + inlen, 1, incap - inlen, fin);
        if (got == 0) break;
        inlen += got;
      }
      {
        size_t consumed = 0;
        int had_error = 0;
        size_t total = 0;
        unsigned char *data = NULL;
        size_t datalen = 0;
        unsigned char *p = inbuf;
        size_t left = inlen;
        int ok = 1;
        while (left > 0) {
          unsigned char *chunk = NULL; size_t chunklen = 0;
          if (DecodeStream(p, left, &consumed, &chunk, &chunklen, &had_error) != 0) { ok = 0; break; }
          if (consumed == 0) { ok = 0; break; }
          { unsigned char *nb = realloc(data, datalen + chunklen);
            if (!nb) { ok = 0; break; }
            data = nb; memcpy(data + datalen, chunk, chunklen); datalen += chunklen; }
          free(chunk);
          if (!o.mode_concat) break;
          p += consumed; left -= consumed;
        }
        if (!ok) {
          fprintf(stderr, "corrupt input [%s]\n", inname);
          free(data);
          rc = 1; goto cleanup;
        }
        outbuf = data; outlen = datalen;
      }
      if (o.mode_test) {
        if (o.mode_verbose) PrintTiming("Decompressed", inname, inlen, outlen);
      } else if (o.mode_stdout) {
        fwrite(outbuf, 1, outlen, stdout);
        if (o.mode_verbose) PrintTiming("Decompressed", inname, inlen, outlen);
      } else {
        if (o.output) outname = strdup(o.output);
        else {
          size_t sl = strlen(o.suffix);
          size_t l = strlen(inname);
          if (l >= sl && !strcmp(inname + l - sl, o.suffix)) {
            outname = malloc(l - sl + 1);
            memcpy(outname, inname, l - sl); outname[l - sl] = 0;
          } else {
            outname = malloc(l + 1); memcpy(outname, inname, l); outname[l] = 0;
          }
        }
        if (!o.mode_force && !use_stdin) {
          struct stat st2;
          if (stat(outname, &st2) == 0) {
            fprintf(stderr, "failed to open output file [%s]: File exists\n", outname);
            rc = 1; goto cleanup;
          }
        }
        { FILE *t = fopen(outname, "wb");
          if (!t) { fprintf(stderr, "failed to open output file [%s]: %s\n", outname, strerror(errno)); rc = 1; goto cleanup; }
          fwrite(outbuf, 1, outlen, t);
          fclose(t); }
        if (o.mode_copy_stat && !use_stdin) CopyStat(inname, outname);
        if (o.mode_verbose) PrintTiming("Decompressed", inname, inlen, outlen);
        if (o.mode_rm && !use_stdin) destroy_src = 1;
      }
    }
cleanup:
    if (fin && fin != stdin) fclose(fin);
    if (fout) fclose(fout);
    free(inbuf); free(outbuf); free(outname);
    if (destroy_src) unlink(inname);
    if (rc) break;
  }
  free(files);
  return rc;
}
EOF
cat > compile.sh <<'EOF'
#!/bin/sh
set -e
cd "$(dirname "$0")"
gcc -O2 -std=gnu99 -Wall -o executable src/brotli.c
EOF
chmod +x compile.sh && ./compile.sh && echo BUILD_OK && ls -la executable"}

actions.command:
mkdir -p /workspace/src && cd /workspace && cat > src/brotli.c <<'EOF'
/* brotli-like command line tool (clean reimplementation from observed behaviour) */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <utime.h>
#include <getopt.h>
#include <grp.h>
#include <pwd.h>

#define PROGRAM_NAME "executable"
#define BROTLI_VERSION_STRING "brotli 1.2.0"

/* ------------------------------------------------------------------ */
/* usage / help                                                       */
/* ------------------------------------------------------------------ */
static const char *const kUsage[] = {
"Usage: " PROGRAM_NAME " [OPTION]... [FILE]...",
"Options:",
"  -#                          compression level (0-9)",
"  -c, --stdout                write on standard output",
"  -d, --decompress            decompress",
"  -f, --force                 force output file overwrite",
"  -h, --help                  display this help and exit",
"  -j, --rm                    remove source file(s)",
"  -s, --squash                remove destination file if larger than source",
"  -k, --keep                  keep source file(s) (default)",
"  -n, --no-copy-stat          do not copy source file(s) attributes",
"  -o FILE, --output=FILE      output file (only if 1 input file)",
"  -q NUM, --quality=NUM       compression level (0-11)",
"  -t, --test                  test compressed file integrity",
"  -v, --verbose               verbose mode",
"  -w NUM, --lgwin=NUM         set LZ77 window size (0, 10-24)",
"                              window size = 2**NUM - 16",
"                              0 lets compressor choose the optimal value",
"  --large_window=NUM          use incompatible large-window brotli",
"                              bitstream with window size (0, 10-30)",
"                              WARNING: this format is not compatible",
"                              with brotli RFC 7932 and may not be",
"                              decodable with regular brotli decoders",
"  -C B64, --comment=B64       set comment; argument is base64-decoded first;",
"                              (maximal decoded length: 80)",
"                              when decoding: check stream comment;",
"                              when encoding: embed comment (fingerprint)",
"  -D FILE, --dictionary=FILE  use FILE as raw (LZ77) dictionary",
"  -K, --concatenated          allows concatenated brotli streams as input",
"  -S SUF, --suffix=SUF        output file suffix (default:'.br')",
"  -V, --version               display version and exit",
"  -Z, --best                  use best compression level (11) (default)",
"Simple options could be coalesced, i.e. '-9kf' is equivalent to '-9 -k -f'.",
"With no FILE, or when FILE is -, read standard input.",
"All arguments after '--' are treated as files.",
NULL};

static void PrintUsage(FILE *out) {
  int i;
  for (i = 0; kUsage[i]; i++) fprintf(out, "%s\n", kUsage[i]);
}

static void Fatal(void) {
  PrintUsage(stdout);
  exit(1);
}

/* ------------------------------------------------------------------ */
/* options                                                            */
/* ------------------------------------------------------------------ */
typedef struct {
  int mode_decompress, mode_test, mode_verbose, mode_stdout, mode_rm;
  int mode_keep, mode_copy_stat, mode_force, mode_squash, mode_concat;
  int quality;
  int lgwin;            /* -1 = not set */
  int large_window;
  const char *suffix;
  const char *output;
  const char *dictionary;
  unsigned char comment[80];
  int comment_len;
  int have_comment;
  int dictionary_set;
  int have_quality, have_lgwin, have_output, have_suffix, have_dictionary;
  int have_comment_opt;
  int version;
  int help;
} Options;

static int ParseInt(const char *s, int *out) {
  char *end = NULL;
  long v;
  if (!s || !*s) return 0;
  v = strtol(s, &end, 10);
  if (end == s || *end) return 0;
  *out = (int)v;
  return 1;
}

static int Base64Decode(const char *in, unsigned char *out, int maxlen) {
  static const int tbl[256] = {0};
  static int init = 0;
  int i, acc = 0, bits = 0, len = 0;
  int T[256];
  if (!init) {
    const char *cs = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    for (i = 0; i < 256; i++) T[i] = -1;
    for (i = 0; i < 64; i++) T[(unsigned char)cs[i]] = i;
    init = 1;
    for (i = 0; i < 256; i++) ((int*)tbl)[i] = T[i];
  } else {
    for (i = 0; i < 256; i++) T[i] = ((const int*)tbl)[i];
  }
  {
    /* recompute each time (simple, avoids global state bugs) */
    const char *cs = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    int j;
    for (j = 0; j < 256; j++) T[j] = -1;
    for (j = 0; j < 64; j++) T[(unsigned char)cs[j]] = j;
  }
  for (i = 0; in[i]; i++) {
    int c = (unsigned char)in[i];
    int v;
    if (c == '=') {
      if (in[i+1]) return -1;
      break;
    }
    v = T[c];
    if (v < 0) return -1;
    acc = (acc << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      if (len >= maxlen) return -1;
      out[len++] = (unsigned char)(acc >> bits);
    }
  }
  if (bits >= 6) return -1;  /* dangling bits */
  return len;
}

/* ------------------------------------------------------------------ */
/* bit writer / reader                                                */
/* ------------------------------------------------------------------ */
typedef struct { unsigned char *buf; size_t cap, len; uint32_t acc; int nbits; } BitW;

static void bw_init(BitW *w) { w->buf = NULL; w->cap = 0; w->len = 0; w->acc = 0; w->nbits = 0; }
static void bw_free(BitW *w) { free(w->buf); w->buf = NULL; }
static void bw_put(BitW *w, uint32_t val, int n) {
  int i;
  for (i = 0; i < n; i++) {
    w->acc |= ((val >> i) & 1u) << w->nbits;
    w->nbits++;
    if (w->nbits == 8) {
      if (w->len == w->cap) { w->cap = w->cap ? w->cap * 2 : 4096; w->buf = realloc(w->buf, w->cap); }
      w->buf[w->len++] = (unsigned char)w->acc;
      w->acc = 0; w->nbits = 0;
    }
  }
}
static void bw_align(BitW *w) { while (w->nbits) bw_put(w, 0, 1); }
static unsigned char *bw_bytes(BitW *w, size_t *len) {
  bw_align(w);
  *len = w->len;
  return w->buf;
}

/* ------------------------------------------------------------------ */
/* stream construction: uncompressed meta-blocks                      */
/* ------------------------------------------------------------------ */
static void PutWindowBits(BitW *w, int lgwin, int large_window) {
  if (!large_window) {
    if (lgwin == 16) { bw_put(w, 0, 1); return; }
    if (lgwin >= 17 && lgwin <= 24) { bw_put(w, 1, 1); bw_put(w, (unsigned)(lgwin - 17), 3); return; }
    bw_put(w, 1, 1); bw_put(w, 0, 3); bw_put(w, (unsigned)(lgwin - 8), 3);
    return;
  }
  if (lgwin >= 10 && lgwin <= 24) { PutWindowBits(w, lgwin, 0); return; }
  if (lgwin >= 25 && lgwin <= 30) {
    bw_put(w, 1, 1); bw_put(w, 0, 3); bw_put(w, 1, 3); bw_put(w, (unsigned)lgwin, 5);
    return;
  }
  PutWindowBits(w, lgwin, 0);
}

/* number of bits needed */
static int NibblesForMlen(uint32_t mlen1) {
  int x = 0;
  while (x < 3 && mlen1 >= (1u << (12 + 4 * (x + 1)))) x++;
  if (mlen1 >= 65536u) {
    while (x < 2 && mlen1 >= (1u << (16 + 4 * (x + 1)))) x++;
  }
  return x;
}

static void PutMetablockHeader(BitW *w, int is_last, uint32_t mlen, int is_uncompressed) {
  int x;
  bw_put(w, is_last ? 1u : 0u, 1);
  if (is_last) bw_put(w, 0u, 1); /* is_last_empty = 0 */
  x = NibblesForMlen(mlen - 1);
  bw_put(w, (unsigned)x, 2);
  bw_put(w, mlen - 1, 16 + 4 * x);
  if (is_uncompressed) bw_put(w, 1u, 1);
  else bw_put(w, 0u, 1);
}

/* write whole stream as sequence of uncompressed meta blocks */
static int EncodeUncompressed(const unsigned char *data, size_t len, int lgwin,
                              int large_window, const unsigned char *comment, int clen,
                              unsigned char **outp, size_t *outlen) {
  BitW w;
  size_t pos = 0;
  size_t total_cap = len + 64;
  unsigned char *acc = NULL;
  size_t acc_len = 0, acc_cap = 0;
  bw_init(&w);
  PutWindowBits(&w, lgwin, large_window);
  if (len == 0) {
    bw_put(&w, 1, 1); /* is_last */
    bw_put(&w, 1, 1); /* is_last_empty */
  }
  while (pos < len) {
    size_t chunk = len - pos;
    if (chunk > 524288) chunk = 524288;
    PutMetablockHeader(&w, (pos + chunk == len) ? 1 : 0, (uint32_t)chunk, 1);
    bw_align(&w);
    { size_t l; unsigned char *b = bw_bytes(&w, &l);
      if (acc_len + l > acc_cap) { acc_cap = (acc_len + l + len + 64); acc = realloc(acc, acc_cap); }
      memcpy(acc + acc_len, b, l); acc_len += l; }
    free(w.buf); w.buf = NULL; w.cap = 0; w.len = 0; w.acc = 0; w.nbits = 0;
    { size_t i; for (i = 0; i < chunk; i++) {
        if (acc_len == acc_cap) { acc_cap *= 2; acc = realloc(acc, acc_cap); }
        acc[acc_len++] = data[pos + i];
      } }
    pos += chunk;
  }
  if (len == 0) { size_t l; unsigned char *b = bw_bytes(&w, &l);
    if (acc_len + l > acc_cap) { acc_cap = acc_len + l + 8; acc = realloc(acc, acc_cap); }
    memcpy(acc + acc_len, b, l); acc_len += l; free(w.buf); w.buf=NULL; }
  else { free(w.buf); }
  *outp = acc; *outlen = acc_len;
  return 0;
}

/* ------------------------------------------------------------------ */
/* decoding: minimal brotli decoder                                   */
/* ------------------------------------------------------------------ */
typedef struct {
  const unsigned char *buf;
  size_t len, pos;
  uint32_t acc;
  int nbits;
} BitR;

static int br_init(BitR *r, const unsigned char *b, size_t l) {
  r->buf = b; r->len = l; r->pos = 0; r->acc = 0; r->nbits = 0;
  return 1;
}
static int br_fill(BitR *r, int n) {
  while (r->nbits < n) {
    if (r->pos >= r->len) return 0;
    r->acc |= (uint32_t)r->buf[r->pos++] << r->nbits;
    r->nbits += 8;
  }
  return 1;
}
static int br_read(BitR *r, int n, uint32_t *out) {
  if (n == 0) { *out = 0; return 1; }
  if (!br_fill(r, n)) return 0;
  *out = r->acc & ((1u << n) - 1u);
  r->acc >>= n; r->nbits -= n;
  return 1;
}
static void br_align(BitR *r) { r->acc = 0; r->nbits = 0; }

static int ReadWindowBits(BitR *r, int *lgwin) {
  uint32_t b;
  if (!br_read(r, 1, &b)) return 0;
  if (!b) { *lgwin = 16; return 1; }
  if (!br_read(r, 3, &b)) return 0;
  if (b) { *lgwin = 17 + (int)b; return 1; }
  if (!br_read(r, 3, &b)) return 0;
  if (b == 1) { if (!br_read(r, 5, &b)) return 0; *lgwin = (int)b; return 1; }
  if (b == 0) { *lgwin = 17; return 1; }
  *lgwin = (int)b + 8;
  return 1;
}

/* decode a stream; returns 0 on success */
static int DecodeStream(const unsigned char *in, size_t inlen, size_t *consumed,
                        unsigned char **outp, size_t *outlen, int *had_error) {
  BitR r;
  uint32_t v;
  int lgwin, is_last, is_last_empty, x, is_uncomp;
  uint32_t mlen;
  if (!br_init(&r, in, inlen)) return 1;
  if (!ReadWindowBits(&r, &lgwin)) return 1;
  *outp = NULL; *outlen = 0; *had_error = 0;
  for (;;) {
    size_t op;
    unsigned char *nb;
    if (!br_read(&r, 1, &v)) return 1;
    is_last = (int)v;
    if (is_last) {
      if (!br_read(&r, 1, &v)) return 1;
      is_last_empty = (int)v;
      if (is_last_empty) { *consumed = r.pos - (size_t)(r.nbits / 8); break; }
    }
    if (!br_read(&r, 2, &v)) return 1;
    x = (int)v;
    if (x > 2) return 1;
    if (!br_read(&r, 16 + 4 * x, &v)) return 1;
    mlen = v + 1;
    if (mlen > (1u << 24)) return 1;
    if (x > 0) {
      if (mlen - 1 < (1u << (12 + 4 * x))) return 1;
    }
    if (!br_read(&r, 1, &v)) return 1;
    is_uncomp = (int)v;
    if (!is_uncomp) return 1;   /* compressed meta-blocks not supported */
    br_align(&r);
    nb = realloc(*outp, *outlen + mlen);
    if (!nb) return 1;
    *outp = nb;
    for (op = 0; op < mlen; op++) {
      if (!br_fill(&r, 8)) return 1;
      nb[*outlen + op] = (unsigned char)(r.acc & 0xffu);
      r.acc >>= 8; r.nbits -= 8;
    }
    *outlen += mlen;
    if (is_last) {
      *consumed = r.pos - (size_t)(r.nbits / 8);
      break;
    }
  }
  return 0;
}

/* ------------------------------------------------------------------ */
/* file helpers                                                       */
/* ------------------------------------------------------------------ */
static int CopyStat(const char *src, const char *dst) {
  struct stat st;
  if (stat(src, &st) != 0) return 0;
  {
    struct utimbuf tb;
    tb.actime = st.st_atime;
    tb.modtime = st.st_mtime;
    if (chmod(dst, st.st_mode & 07777) != 0)
      fprintf(stderr, "setting access bits failed for [%s]: %s\n", dst, strerror(errno));
    if (chown(dst, st.st_uid, (gid_t)-1) != 0 && (geteuid() != st.st_uid))
      fprintf(stderr, "setting user failed for [%s]: %s\n", dst, strerror(errno));
    if (chown(dst, (uid_t)-1, st.st_gid) != 0 && (getegid() != st.st_gid))
      fprintf(stderr, "setting group failed for [%s]: %s\n", dst, strerror(errno));
    utime(dst, &tb);
  }
  return 1;
}

static void PrintTiming(const char *kind, const char *name, size_t in, size_t out) {
  fprintf(stderr, "%s [%s]: %zu B -> %zu B in 0.00 sec\n", kind, name, in, out);
}

/* ------------------------------------------------------------------ */
int main(int argc, char **argv) {
  Options o;
  int i, argi, nfiles = 0;
  char **files;
  int args_end = 0;
  int rc = 0;

  memset(&o, 0, sizeof(o));
  o.quality = 11;
  o.lgwin = -1;
  o.large_window = -1;
  o.suffix = ".br";
  o.mode_keep = 1;
  o.mode_copy_stat = 1;

  files = (char **)malloc(sizeof(char *) * (argc + 2));
  if (!files) return 1;

  for (argi = 1; argi < argc; argi++) {
    char *a = argv[argi];
    if (!args_end && a[0] == '-' && a[1]) {
      if (a[1] == '-') {
        /* long option */
        char *name = a + 2, *eq = strchr(name, '=');
        size_t nl = eq ? (size_t)(eq - name) : strlen(name);
        char tmp[64];
        if (nl >= sizeof(tmp)) nl = sizeof(tmp) - 1;
        memcpy(tmp, name, nl); tmp[nl] = 0;
        if (!strcmp(tmp, "")) { args_end = 1; continue; }
        else if (!strcmp(tmp, "decompress")) o.mode_decompress = 1;
        else if (!strcmp(tmp, "stdout")) o.mode_stdout = 1;
        else if (!strcmp(tmp, "test")) o.mode_test = 1;
        else if (!strcmp(tmp, "force")) o.mode_force = 1;
        else if (!strcmp(tmp, "help")) { PrintUsage(stderr); exit(0); }
        else if (!strcmp(tmp, "version")) { puts(BROTLI_VERSION_STRING); exit(0); }
        else if (!strcmp(tmp, "rm")) o.mode_rm = 1;
        else if (!strcmp(tmp, "keep")) o.mode_keep = 1;
        else if (!strcmp(tmp, "squash")) o.mode_squash = 1;
        else if (!strcmp(tmp, "no-copy-stat")) o.mode_copy_stat = 0;
        else if (!strcmp(tmp, "concatenated")) o.mode_concat = 1;
        else if (!strcmp(tmp, "verbose")) {
          if (o.mode_verbose) { fprintf(stderr, "argument --verbose / -v already set\n"); Fatal(); }
          o.mode_verbose = 1;
        }
        else if (!strcmp(tmp, "quality") || !strcmp(tmp, "lgwin") ||
                 !strcmp(tmp, "large_window") || !strcmp(tmp, "output") ||
                 !strcmp(tmp, "suffix") || !strcmp(tmp, "comment") ||
                 !strcmp(tmp, "dictionary")) {
          const char *val;
          if (!eq) { fprintf(stderr, "must pass the parameter as --%s=value\n", tmp); Fatal(); }
          val = eq + 1;
          if (!strcmp(tmp, "quality")) {
            if (o.have_quality) { fprintf(stderr, "argument --quality / -q already set\n"); Fatal(); }
            if (!ParseInt(val, &o.quality) || o.quality < 0 || o.quality > 11) {
              fprintf(stderr, "error parsing quality value [%s]\n", val); Fatal();
            }
            o.have_quality = 1;
          } else if (!strcmp(tmp, "lgwin")) {
            if (o.have_lgwin) { fprintf(stderr, "argument --lgwin / -w already set\n"); Fatal(); }
            if (!ParseInt(val, &o.lgwin)) { fprintf(stderr, "error parsing lgwin value [%s]\n", val); Fatal(); }
            if (o.lgwin < 10) { fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (10)\n", o.lgwin); Fatal(); }
            if (!o.large_window && o.lgwin > 24) { fprintf(stderr, "error parsing lgwin value [%s]\n", val); Fatal(); }
            o.have_lgwin = 1;
          } else if (!strcmp(tmp, "large_window")) {
            if (o.have_lgwin) { fprintf(stderr, "argument --lgwin / -w already set\n"); Fatal(); }
            if (!ParseInt(val, &o.lgwin)) { fprintf(stderr, "error parsing lgwin value [%s]\n", val); Fatal(); }
            if (o.lgwin < 10) { fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (10)\n", o.lgwin); Fatal(); }
            if (o.lgwin > 30) { fprintf(stderr, "error parsing lgwin value [%s]\n", val); Fatal(); }
            o.large_window = 1; o.have_lgwin = 1;
          } else if (!strcmp(tmp, "output")) {
            if (o.have_output) { fprintf(stderr, "argument --output / -o already set\n"); Fatal(); }
            o.output = val; o.have_output = 1;
          } else if (!strcmp(tmp, "suffix")) {
            if (o.have_suffix) { fprintf(stderr, "argument --suffix / -S already set\n"); Fatal(); }
            o.suffix = val; o.have_suffix = 1;
          } else if (!strcmp(tmp, "comment")) {
            int n = Base64Decode(val, o.comment, 80);
            if (n < 0) { fprintf(stderr, "invalid base64-encoded comment\n"); Fatal(); }
            o.comment_len = n; o.have_comment = 1; o.have_comment_opt = 1;
          } else {
            if (o.have_dictionary) { fprintf(stderr, "argument --dictionary / -D already set\n"); Fatal(); }
            o.dictionary = val; o.have_dictionary = 1; o.dictionary_set = 1;
          }
        }
        else { fprintf(stderr, "must pass the parameter as --%s=value\n", tmp); Fatal(); }
        continue;
      }
      /* short options, possibly coalesced */
      {
        char *p = a + 1;
        while (*p) {
          char c = *p;
          switch (c) {
            case 'c': o.mode_stdout = 1; break;
            case 'd': o.mode_decompress = 1; break;
            case 'f': o.mode_force = 1; break;
            case 't': o.mode_test = 1; break;
            case 'j': o.mode_rm = 1; break;
            case 'k': o.mode_keep = 1; break;
            case 's': o.mode_squash = 1; break;
            case 'n': o.mode_copy_stat = 0; break;
            case 'K': o.mode_concat = 1; break;
            case 'Z': o.quality = 11; break;
            case 'v':
              if (o.mode_verbose) { fprintf(stderr, "argument --verbose / -v already set\n"); Fatal(); }
              o.mode_verbose = 1; break;
            case 'h': PrintUsage(stderr); exit(0);
            case 'V': puts(BROTLI_VERSION_STRING); exit(0);
            default: {
              int val_int;
              if (c >= '0' && c <= '9') {
                if (o.have_quality) { fprintf(stderr, "argument --quality / -q already set\n"); Fatal(); }
                o.quality = c - '0'; o.have_quality = 1; p++; continue;
              }
              if (c == 'q' || c == 'w' || c == 'o' || c == 'S' || c == 'C' || c == 'D') {
                const char *val;
                if (p[1]) { val = p + 1; p = ""; }
                else { if (argi + 1 >= argc) { fprintf(stderr, "expected parameter for argument -%c\n", c); Fatal(); }
                       val = argv[++argi]; }
                if (c == 'q') {
                  if (o.have_quality) { fprintf(stderr, "argument --quality / -q already set\n"); Fatal(); }
                  if (!ParseInt(val, &o.quality) || o.quality < 0 || o.quality > 11) {
                    fprintf(stderr, "error parsing quality value [%s]\n", val); Fatal(); }
                  o.have_quality = 1;
                } else if (c == 'w') {
                  if (o.have_lgwin) { fprintf(stderr, "argument --lgwin / -w already set\n"); Fatal(); }
                  if (!ParseInt(val, &o.lgwin)) { fprintf(stderr, "error parsing lgwin value [%s]\n", val); Fatal(); }
                  if (o.lgwin < 10) { fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (10)\n", o.lgwin); Fatal(); }
                  if (o.lgwin > 24) { fprintf(stderr, "error parsing lgwin value [%s]\n", val); Fatal(); }
                  o.have_lgwin = 1;
                } else if (c == 'o') {
                  if (o.have_output) { fprintf(stderr, "argument --output / -o already set\n"); Fatal(); }
                  o.output = val; o.have_output = 1;
                } else if (c == 'S') {
                  if (o.have_suffix) { fprintf(stderr, "argument --suffix / -S already set\n"); Fatal(); }
                  o.suffix = val; o.have_suffix = 1;
                } else if (c == 'C') {
                  int n = Base64Decode(val, o.comment, 80);
                  if (n < 0) { fprintf(stderr, "invalid base64-encoded comment\n"); Fatal(); }
                  o.comment_len = n; o.have_comment = 1; o.have_comment_opt = 1;
                } else {
                  if (o.have_dictionary) { fprintf(stderr, "argument --dictionary / -D already set\n"); Fatal(); }
                  o.dictionary = val; o.have_dictionary = 1; o.dictionary_set = 1;
                }
                break;
              }
              fprintf(stderr, "invalid argument -%c\n", c); Fatal();
            }
          }
          if (!*p) break;
          p++;
        }
      }
      continue;
    }
    if (!args_end && a[0] == '-' && !a[1]) { files[nfiles++] = a; continue; }
    files[nfiles++] = a;
  }

  if (nfiles == 0) { files[0] = (char *)"-"; nfiles = 1; }

  for (i = 0; i < nfiles; i++) {
    const char *inname = files[i];
    int use_stdin = (strcmp(inname, "-") == 0);
    char *outname = NULL;
    FILE *fin = stdin, *fout = NULL;
    unsigned char *inbuf = NULL, *outbuf = NULL;
    size_t inlen = 0, incap = 0, outlen = 0;
    int destroy_src = 0;

    if (!use_stdin) {
      struct stat st;
      if (stat(inname, &st) != 0) {
        fprintf(stderr, "failed to open input file [%s]: %s\n", inname, strerror(errno));
        rc = 1; goto cleanup;
      }
      if (!o.mode_decompress && !o.mode_test && o.lgwin < 0) {
        /* choose window from file size */
        uint64_t sz = (uint64_t)st.st_size;
        int w = 10;
        uint64_t need = sz + 16;
        while ((1ull << w) < need && w < 30) w++;
        if (w < 10) w = 10;
        if (o.quality <= 1) { if (w < 18) w = 18; }
        if (w > 24) w = 24;
        o.lgwin = w;
      }
      fin = fopen(inname, "rb");
      if (!fin) { fprintf(stderr, "failed to open input file [%s]: %s\n", inname, strerror(errno)); rc = 1; goto cleanup; }
    } else if (o.lgwin < 0) {
      o.lgwin = o.large_window ? 24 : (o.quality <= 1 ? 24 : 24);
    }

    if (!o.mode_decompress && !o.mode_test) {
      /* compression */
      while (1) {
        size_t got;
        if (inlen == incap) { incap = incap ? incap * 2 : 65536; inbuf = realloc(inbuf, incap); if (!inbuf) { rc = 1; goto cleanup; } }
        got = fread(inbuf + inlen, 1, incap - inlen, fin);
        if (got == 0) break;
        inlen += got;
      }
      if (ferror(fin)) { fprintf(stderr, "failed to read input [%s]: %s\n", inname, strerror(errno)); rc = 1; goto cleanup; }
      if (EncodeUncompressed(inbuf, inlen, o.lgwin, o.large_window > 0, o.comment, o.comment_len, &outbuf, &outlen) != 0) {
        fprintf(stderr, "compression failed\n"); rc = 1; goto cleanup;
      }
      if (o.mode_stdout) {
        fwrite(outbuf, 1, outlen, stdout);
      } else if (o.output) {
        outname = strdup(o.output);
      } else {
        size_t l = strlen(inname) + strlen(o.suffix) + 1;
        outname = malloc(l); snprintf(outname, l, "%s%s", inname, o.suffix);
      }
      if (!o.mode_stdout) {
        FILE *t;
        if (!o.mode_force && !use_stdin) {
          struct stat st2;
          if (stat(outname, &st2) == 0) {
            fprintf(stderr, "failed to open output file [%s]: File exists\n", outname);
            rc = 1; goto cleanup;
          }
        }
        t = fopen(outname, "wb");
        if (!t) { fprintf(stderr, "failed to open output file [%s]: %s\n", outname, strerror(errno)); rc = 1; goto cleanup; }
        fwrite(outbuf, 1, outlen, t);
        fclose(t);
        if (o.mode_copy_stat && !use_stdin) CopyStat(inname, outname);
        if (o.mode_verbose) PrintTiming("Compressed", inname, inlen, outlen);
        if (o.mode_rm && !use_stdin) destroy_src = 1;
      } else {
        if (o.mode_verbose) PrintTiming("Compressed", inname, inlen, outlen);
        if (o.mode_rm && !use_stdin) destroy_src = 1;
      }
    } else {
      /* decompression / test */
      while (1) {
        size_t got;
        if (inlen == incap) { incap = incap ? incap * 2 : 65536; inbuf = realloc(inbuf, incap); if (!inbuf) { rc = 1; goto cleanup; } }
        got = fread(inbuf + inlen, 1, incap - inlen, fin);
        if (got == 0) break;
        inlen += got;
      }
      {
        size_t consumed = 0;
        int had_error = 0;
        size_t total = 0;
        unsigned char *data = NULL;
        size_t datalen = 0;
        unsigned char *p = inbuf;
        size_t left = inlen;
        int ok = 1;
        while (left > 0) {
          unsigned char *chunk = NULL; size_t chunklen = 0;
          if (DecodeStream(p, left, &consumed, &chunk, &chunklen, &had_error) != 0) { ok = 0; break; }
          if (consumed == 0) { ok = 0; break; }
          { unsigned char *nb = realloc(data, datalen + chunklen);
            if (!nb) { ok = 0; break; }
            data = nb; memcpy(data + datalen, chunk, chunklen); datalen += chunklen; }
          free(chunk);
          if (!o.mode_concat) break;
          p += consumed; left -= consumed;
        }
        if (!ok) {
          fprintf(stderr, "corrupt input [%s]\n", inname);
          free(data);
          rc = 1; goto cleanup;
        }
        outbuf = data; outlen = datalen;
      }
      if (o.mode_test) {
        if (o.mode_verbose) PrintTiming("Decompressed", inname, inlen, outlen);
      } else if (o.mode_stdout) {
        fwrite(outbuf, 1, outlen, stdout);
        if (o.mode_verbose) PrintTiming("Decompressed", inname, inlen, outlen);
      } else {
        if (o.output) outname = strdup(o.output);
        else {
          size_t sl = strlen(o.suffix);
          size_t l = strlen(inname);
          if (l >= sl && !strcmp(inname + l - sl, o.suffix)) {
            outname = malloc(l - sl + 1);
            memcpy(outname, inname, l - sl); outname[l - sl] = 0;
          } else {
