            case 'd': o.mode_decompress = 1; break;
            case 'f': o.mode_force = 1; break;
            case 't': o.mode_test = 1; break;
            case 'j': o.mode_rm = 1; break;
            case 'k': o.mode_keep = 1; break;
            case 's': o.mode_squash = 1; break;
            case 'n': o.mode_copy_stat = 0; break;
            case 'K': o.mode_concat = 1; break;
            case 'Z': o.quality = 11; break;
            case 'v':
