              o.mode_verbose = 1; break;
            case 'h': PrintUsage(stderr); exit(0);
            case 'V': puts(BROTLI_VERSION_STRING); exit(0);
            default: {
              int val_int;
              if (c >= '0' && c <= '9') {
                if (o.have_quality) { fprintf(stderr, "argument --quality / -q already set\n"); Fatal(); }
                o.quality = c - '0'; o.have_quality = 1; p++; continue;
              }
              if (c == 'q' || c == 'w' || c == 'o' || c == 'S' || c == 'C' || c == 'D') {
                const char *val;
                if (p[1]) { val = p + 1; p = ""; }
                else { if (argi + 1 >= argc) { fprintf(stderr, "expected parameter for argument -%c\n", c); Fatal(); }
                       val = argv[++argi]; }
                if (c == 'q') {
                  if (o.have_quality) { fprintf(stderr, "argument --quality / -q already set\n"); Fatal(); }
                  if (!ParseInt(val, &o.quality) || o.quality < 0 || o.quality > 11) {
                    fprintf(stderr, "error parsing quality value [%s]\n", val); Fatal(); }
                  o.have_quality = 1;
                } else if (c == 'w') {
                  if (o.have_lgwin) { fprintf(stderr, "argument --lgwin / -w already set\n"); Fatal(); }
                  if (!ParseInt(val, &o.lgwin)) { fprintf(stderr, "error parsing lgwin value [%s]\n", val); Fatal(); }
                  if (o.lgwin < 10) { fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (10)\n", o.lgwin); Fatal(); }
                  if (o.lgwin > 24) { fprintf(stderr, "error parsing lgwin value [%s]\n", val); Fatal(); }
                  o.have_lgwin = 1;
                } else if (c == 'o') {
                  if (o.have_output) { fprintf(stderr, "argument --output / -o already set\n"); Fatal(); }
                  o.output = val; o.have_output = 1;
                } else if (c == 'S') {
                  if (o.have_suffix) { fprintf(stderr, "argument --suffix / -S already set\n"); Fatal(); }
                  o.suffix = val; o.have_suffix = 1;
                } else if (c == 'C') {
                  int n = Base64Decode(val, o.comment, 80);
                  if (n < 0) { fprintf(stderr, "invalid base64-encoded comment\n"); Fatal(); }
                  o.comment_len = n; o.have_comment = 1; o.have_comment_opt = 1;
                } else {
                  if (o.have_dictionary) { fprintf(stderr, "argument --dictionary / -D already set\n"); Fatal(); }
                  o.dictionary = val; o.have_dictionary = 1; o.dictionary_set = 1;
                }
                break;
              }
              fprintf(stderr, "invalid argument -%c\n", c); Fatal();
            }
          }
          if (!*p) break;
          p++;
        }
      }
      continue;
    }
    if (!args_end && a[0] == '-' && !a[1]) { files[nfiles++] = a; continue; }
    files[nfiles++] = a;
  }

  if (nfiles == 0) { files[0] = (char *)"-"; nfiles = 1; }

  for (i = 0; i < nfiles; i++) {
    const char *inname = files[i];
    int use_stdin = (strcmp(inname, "-") == 0);
    char *outname = NULL;
    FILE *fin = stdin, *fout = NULL;
    unsigned char *inbuf = NULL, *outbuf = NULL;
    size_t inlen = 0, incap = 0, outlen = 0;
    int destroy_src = 0;

    if (!use_stdin) {
      struct stat st;
      if (stat(inname, &st) != 0) {
        fprintf(stderr, "failed to open input file [%s]: %s\n", inname, strerror(errno));
        rc = 1; goto cleanup;
      }
      if (!o.mode_decompress && !o.mode_test && o.lgwin < 0) {
        /* choose window from file size */
        uint64_t sz = (uint64_t)st.st_size;
        int w = 10;
        uint64_t need = sz + 16;
        while ((1ull << w) < need && w < 30) w++;
        if (w < 10) w = 10;
        if (o.quality <= 1) { if (w < 18) w = 18; }
        if (w > 24) w = 24;
        o.lgwin = w;
      }
      fin = fopen(inname, "rb");
      if (!fin) { fprintf(stderr, "failed to open input file [%s]: %s\n", inname, strerror(errno)); rc = 1; goto cleanup; }
    } else if (o.lgwin < 0) {
      o.lgwin = o.large_window ? 24 : (o.quality <= 1 ? 24 : 24);
    }

    if (!o.mode_decompress && !o.mode_test) {
      /* compression */
      while (1) {
        size_t got;
        if (inlen == incap) { incap = incap ? incap * 2 : 65536; inbuf = realloc(inbuf, incap); if (!inbuf) { rc = 1; goto cleanup; } }
        got = fread(inbuf + inlen, 1, incap - inlen, fin);
        if (got == 0) break;
        inlen += got;
      }
      if (ferror(fin)) { fprintf(stderr, "failed to read input [%s]: %s\n", inname, strerror(errno)); rc = 1; goto cleanup; }
      if (EncodeUncompressed(inbuf, inlen, o.lgwin, o.large_window > 0, o.comment, o.comment_len, &outbuf, &outlen) != 0) {
        fprintf(stderr, "compression failed\n"); rc = 1; goto cleanup;
      }
      if (o.mode_stdout) {
        fwrite(outbuf, 1, outlen, stdout);
      } else if (o.output) {
        outname = strdup(o.output);
      } else {
        size_t l = strlen(inname) + strlen(o.suffix) + 1;
        outname = malloc(l); snprintf(outname, l, "%s%s", inname, o.suffix);
      }
      if (!o.mode_stdout) {
        FILE *t;
        if (!o.mode_force && !use_stdin) {
          struct stat st2;
          if (stat(outname, &st2) == 0) {
            fprintf(stderr, "failed to open output file [%s]: File exists\n", outname);
            rc = 1; goto cleanup;
          }
        }
        t = fopen(outname, "wb");
        if (!t) { fprintf(stderr, "failed to open output file [%s]: %s\n", outname, strerror(errno)); rc = 1; goto cleanup; }
        fwrite(outbuf, 1, outlen, t);
        fclose(t);
        if (o.mode_copy_stat && !use_stdin) CopyStat(inname, outname);
        if (o.mode_verbose) PrintTiming("Compressed", inname, inlen, outlen);
        if (o.mode_rm && !use_stdin) destroy_src = 1;
      } else {
        if (o.mode_verbose) PrintTiming("Compressed", inname, inlen, outlen);
        if (o.mode_rm && !use_stdin) destroy_src = 1;
      }
    } else {
      /* decompression / test */
      while (1) {
        size_t got;
        if (inlen == incap) { incap = incap ? incap * 2 : 65536; inbuf = realloc(inbuf, incap); if (!inbuf) { rc = 1; goto cleanup; } }
        got = fread(inbuf + inlen, 1, incap - inlen, fin);
        if (got == 0) break;
        inlen += got;
      }
      {
        size_t consumed = 0;
        int had_error = 0;
        size_t total = 0;
        unsigned char *data = NULL;
        size_t datalen = 0;
        unsigned char *p = inbuf;
        size_t left = inlen;
        int ok = 1;
        while (left > 0) {
          unsigned char *chunk = NULL; size_t chunklen = 0;
          if (DecodeStream(p, left, &consumed, &chunk, &chunklen, &had_error) != 0) { ok = 0; break; }
          if (consumed == 0) { ok = 0; break; }
          { unsigned char *nb = realloc(data, datalen + chunklen);
            if (!nb) { ok = 0; break; }
            data = nb; memcpy(data + datalen, chunk, chunklen); datalen += chunklen; }
          free(chunk);
          if (!o.mode_concat) break;
          p += consumed; left -= consumed;
        }
        if (!ok) {
          fprintf(stderr, "corrupt input [%s]\n", inname);
          free(data);
          rc = 1; goto cleanup;
        }
        outbuf = data; outlen = datalen;
      }
      if (o.mode_test) {
        if (o.mode_verbose) PrintTiming("Decompressed", inname, inlen, outlen);
      } else if (o.mode_stdout) {
        fwrite(outbuf, 1, outlen, stdout);
        if (o.mode_verbose) PrintTiming("Decompressed", inname, inlen, outlen);
      } else {
        if (o.output) outname = strdup(o.output);
        else {
          size_t sl = strlen(o.suffix);
          size_t l = strlen(inname);
          if (l >= sl && !strcmp(inname + l - sl, o.suffix)) {
            outname = malloc(l - sl + 1);
            memcpy(outname, inname, l - sl); outname[l - sl] = 0;
          } else {
            outname = malloc(l + 1); memcpy(outname, inname, l); outname[l] = 0;
          }
        }
        if (!o.mode_force && !use_stdin) {
          struct stat st2;
          if (stat(outname, &st2) == 0) {
            fprintf(stderr, "failed to open output file [%s]: File exists\n", outname);
            rc = 1; goto cleanup;
          }
        }
        { FILE *t = fopen(outname, "wb");
          if (!t) { fprintf(stderr, "failed to open output file [%s]: %s\n", outname, strerror(errno)); rc = 1; goto cleanup; }
          fwrite(outbuf, 1, outlen, t);
          fclose(t); }
        if (o.mode_copy_stat && !use_stdin) CopyStat(inname, outname);
        if (o.mode_verbose) PrintTiming("Decompressed", inname, inlen, outlen);
        if (o.mode_rm && !use_stdin) destroy_src = 1;
      }
    }
cleanup:
    if (fin && fin != stdin) fclose(fin);
    if (fout) fclose(fout);
    free(inbuf); free(outbuf); free(outname);
    if (destroy_src) unlink(inname);
    if (rc) break;
  }
  free(files);
  return rc;
}
EOF
cat > compile.sh <<'EOF'
#!/bin/sh
set -e
cd "$(dirname "$0")"
gcc -O2 -std=gnu99 -Wall -o executable src/brotli.c
EOF
chmod +x compile.sh && ./compile.sh && echo BUILD_OK && ls -la executable"}
